@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap');

.pod-root {
  --bg: var(--pn-09090b, #09090b);
  --card: var(--pn-18181b-06, rgba(24, 24, 27, 0.6));
  --border: var(--pn-ffffff-01, rgba(255, 255, 255, 0.1));
  --text: var(--pn-fafafa, #fafafa);
  --primary: var(--pod-accent, #c084fc);
  --primary-hover: var(--pod-accent, #d8b4fe);
  --accent: #facc15;
}

.pod-root * { box-sizing: border-box; margin: 0; padding: 0; }

.pod-root {
  background-color: var(--bg);
  background-image: 
    radial-gradient(circle at 15% 50%, rgba(var(--pod-accent-rgb, 192,132,252), 0.15) 0%, transparent 50%),
    radial-gradient(circle at 85% 30%, rgba(250, 204, 21, 0.1) 0%, transparent 50%);
  color: var(--text);
  font-family: 'Inter', -apple-system, sans-serif;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  overflow-x: hidden;
}

/* Secret Room Password Overlay */
.pod-root #password-overlay {
  position: fixed;
  inset: 0;
  background: var(--pn-09090b-085, rgba(9, 9, 11, 0.85));
  backdrop-filter: blur(12px);
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.5s ease, visibility 0.5s ease;
}

.pod-root .pw-box {
  background: var(--card);
  border: 1px solid var(--border);
  padding: 3rem 2rem;
  border-radius: 1.5rem;
  width: 90%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 25px 50px -12px var(--pn-000000-05, rgba(0, 0, 0, 0.5));
  animation: floatIn 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes floatIn {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.pod-root .pw-box h2 {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
  background: linear-gradient(to right, var(--pn-ffffff, #fff), var(--pod-accent, #c084fc));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.pod-root .pw-box p { color: var(--pn-a1a1aa, #a1a1aa); font-size: 0.9rem; margin-bottom: 2rem; }

.pod-root input {
  width: 100%;
  padding: 1rem;
  background: var(--pn-000000-05, rgba(0, 0, 0, 0.5));
  border: 1px solid var(--pn-ffffff-02, rgba(255, 255, 255, 0.2));
  border-radius: 0.75rem;
  color: white;
  text-align: center;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  margin-bottom: 1rem;
}
.pod-root input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px rgba(var(--pod-accent-rgb, 192,132,252), 0.3);
}

.pod-root button {
  width: 100%;
  padding: 1rem;
  background: linear-gradient(135deg, var(--primary), #9333ea);
  color: white;
  border: none;
  border-radius: 0.75rem;
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s;
}
.pod-root button:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px -10px rgba(var(--pod-accent-rgb, 192,132,252), 0.6);
}
.pod-root .error-msg { color: var(--pt-ef4444, #ef4444); font-size: 0.85rem; margin-top: 1rem; display: none; }

/* Main Content */
.pod-root #main-content {
  display: none;
  width: 100%;
  max-width: 800px;
  padding: 4rem 2rem;
  animation: fadeIn 1s ease forwards;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.pod-root .header-section { text-align: center; margin-bottom: 4rem; }
.pod-root .header-section h1 { 
  font-size: 2.5rem; 
  font-weight: 800; 
  margin-bottom: 1rem;
  background: linear-gradient(to right, var(--pn-ffffff, #fff), #facc15);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.pod-root .header-section p { color: var(--pn-a1a1aa, #a1a1aa); font-size: 1.1rem; line-height: 1.6; }

.pod-root .downloads-grid {
  display: grid;
  gap: 1.5rem;
}

.pod-root .download-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--card);
  border: 1px solid var(--border);
  padding: 1.5rem 2rem;
  border-radius: 1.25rem;
  backdrop-filter: blur(20px);
  transition: all 0.3s;
}
.pod-root .download-card:hover {
  transform: translateX(5px);
  border-color: var(--pn-ffffff-03, rgba(255, 255, 255, 0.3));
  box-shadow: 0 10px 30px var(--pn-000000-03, rgba(0, 0, 0, 0.3));
}

.pod-root .card-info { flex: 1; padding-right: 2rem; }
.pod-root .card-info h3 { font-size: 1.2rem; font-weight: 600; margin-bottom: 0.25rem; display: flex; align-items: center; gap: 0.5rem; }
.pod-root .card-info p { color: var(--pn-a1a1aa, #a1a1aa); font-size: 0.9rem; }

.pod-root .download-btn {
  padding: 0.75rem 2rem;
  background: white;
  color: black;
  font-weight: 700;
  text-decoration: none;
  border-radius: 2rem;
  transition: all 0.2s;
  white-space: nowrap;
}
.pod-root .download-btn:hover {
  background: var(--pn-e4e4e7, #e4e4e7);
  transform: scale(1.05);
}

.pod-root .download-btn.accent {
  background: linear-gradient(135deg, #facc15, #eab308);
  color: #1c1917;
}

@media (max-width: 600px) {
  .pod-root .download-card { flex-direction: column; text-align: center; gap: 1.5rem; padding: 2rem 1.5rem; }
  .pod-root .card-info { padding-right: 0; }
  .pod-root .download-btn { width: 100%; }
}

.pod-root{min-height:0;width:100%;max-width:100%;overflow-x:hidden;}

